head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf10106";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf10106.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_equivRedmptVal", fn: function () { return String((dma_pageContext.get("equivRedmptVal") ?? "")); } },
        { childId: "ipt_defrMms", fn: function () { return String((dma_pageContext.get("defrMms") ?? "")); } },
        { childId: "ipt_splitRedmptCnt", fn: function () { return String((dma_pageContext.get("splitRedmptCnt") ?? "")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        (($c.util.getComponent('txt_amtStr') && $c.util.getComponent('txt_amtStr').setValue) ? $c.util.getComponent('txt_amtStr').setValue($c.num.formatNumberKor(String(((($("#ipt_equivRedmptVal")[0]) && ($("#ipt_equivRedmptVal")[0]).getValue) ? ($("#ipt_equivRedmptVal")[0]).getValue() : (((($("#ipt_equivRedmptVal")[0]) && typeof ($("#ipt_equivRedmptVal")[0]).val === 'function') ? ($("#ipt_equivRedmptVal")[0]).val() : ((($("#ipt_equivRedmptVal")[0]) && ($("#ipt_equivRedmptVal")[0]).value !== undefined) ? ($("#ipt_equivRedmptVal")[0]).value : ($("#ipt_equivRedmptVal")[0]))))) == null ? '' : ((($("#ipt_equivRedmptVal")[0]) && ($("#ipt_equivRedmptVal")[0]).getValue) ? ($("#ipt_equivRedmptVal")[0]).getValue() : (((($("#ipt_equivRedmptVal")[0]) && typeof ($("#ipt_equivRedmptVal")[0]).val === 'function') ? ($("#ipt_equivRedmptVal")[0]).val() : ((($("#ipt_equivRedmptVal")[0]) && ($("#ipt_equivRedmptVal")[0]).value !== undefined) ? ($("#ipt_equivRedmptVal")[0]).value : ($("#ipt_equivRedmptVal")[0])))))).replace(/,/g, ''))) : console.warn('[sdd] num2won 대상 미해결: ' + 'amt_str'));
        $c.num.formatNumber($("#ipt_equivRedmptVal")[0]);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10106.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldinf10106: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_equivRedmptVal_onkeyup
 * @description ipt_equivRedmptVal 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_equivRedmptVal_onkeyup = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        (($c.util.getComponent('txt_amtStr') && $c.util.getComponent('txt_amtStr').setValue) ? $c.util.getComponent('txt_amtStr').setValue($c.num.formatNumberKor(String((((selfVar) && (selfVar).getValue) ? (selfVar).getValue() : ((((selfVar) && typeof (selfVar).val === 'function') ? (selfVar).val() : (((selfVar) && (selfVar).value !== undefined) ? (selfVar).value : (selfVar))))) == null ? '' : (((selfVar) && (selfVar).getValue) ? (selfVar).getValue() : ((((selfVar) && typeof (selfVar).val === 'function') ? (selfVar).val() : (((selfVar) && (selfVar).value !== undefined) ? (selfVar).value : (selfVar)))))).replace(/,/g, ''))) : console.warn('[sdd] num2won 대상 미해결: ' + 'amt_str'));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10106.ipt_equivRedmptVal_onkeyup' }); }
};

/**
 * @method
 * @name btn_sendForm_onclick
 * @description btn_sendForm 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_sendForm_onclick = async function(e){
    try {
        await scwin.sendForm()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf10106.btn_sendForm_onclick' }); }
};

/**
 * @method
 * @name btn_sendCancel_onclick
 * @description btn_sendCancel 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_sendCancel_onclick = function(e){
    try {
        scwin.sendCancel()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10106.btn_sendCancel_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name sendForm
 * @description send Form 처리
 * @param {*} fm fm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sendForm = async function (fm) {
    const defer_trm_int = "";
    if ($c.str.getByteLength($c.util.getComponent('ipt_equivRedmptVal').getValue()) === 0) {
        await $c.win.alert("균등상환액을 입력하세요.");
        $c.util.getComponent("ipt_equivRedmptVal").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_defrMms').getValue()) === 0) {
        await $c.win.alert("거치기간을 입력하세요.");
        $c.util.getComponent("ipt_defrMms").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('slc_redmptPdIntTpCd').getValue()) === 0) {
        await $c.win.alert("거치기간이자를 선택하세요.");
        document.redmpt_pd_int_tp_cd.focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_splitRedmptCnt').getValue()) === 0) {
        await $c.win.alert("분할상환 횟수를 입력하세요.");
        $c.util.getComponent("ipt_splitRedmptCnt").focus();
        return;
    }
    (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById("ipt_equivRedmptVal")) || { setValue: function () {} }).setValue($c.util.getComponent('ipt_equivRedmptVal').getValue());
    (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById("ipt_defrMms")) || { setValue: function () {} }).setValue($c.util.getComponent('ipt_defrMms').getValue());
    (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById("slc_redmptPdIntTpCd")) || { setValue: function () {} }).setValue($c.util.getComponent('slc_redmptPdIntTpCd').getValue());
    (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById("ipt_splitRedmptCnt")) || { setValue: function () {} }).setValue($c.util.getComponent('ipt_splitRedmptCnt').getValue());
    $c.win.closePopup();
};

/**
 * @method
 * @name sendCancel
 * @description send Cancel 처리
 * @returns {void}
 * @hidden N
 */
scwin.sendCancel = function () {
    $c.win.closePopup();
};
